commands.grammar_source:
| unique_opt order_direction INDEX symbol_index_name ON simple_table_name
		{
			CreateIndexNode* node = newNode<CreateIndexNode>(*$4);
			node->unique = $1;
			node->descending = $2;
			node->relation = $6;
			$$ = node;
		}
	index_definition(static_cast<CreateIndexNode*>($7))
		{
			$$ = $7;
		}

